-- Provider credentials are AES-GCM ciphertext; the master key is a Worker secret.
CREATE TABLE cms_ai_settings(provider_id TEXT PRIMARY KEY NOT NULL,encrypted_key TEXT,key_nonce TEXT,key_version TEXT,credential_id TEXT,project_id TEXT NOT NULL DEFAULT '',translation_model TEXT NOT NULL DEFAULT 'gpt-5-mini',translate_enabled INTEGER NOT NULL DEFAULT 1,narration_enabled INTEGER NOT NULL DEFAULT 1,images_enabled INTEGER NOT NULL DEFAULT 1,daily_limit INTEGER NOT NULL DEFAULT 100 CHECK(daily_limit BETWEEN 1 AND 10000),revision INTEGER NOT NULL DEFAULT 1,updated_by TEXT REFERENCES auth_user(id),updated_at INTEGER NOT NULL);
CREATE TABLE cms_ai_grant(grant_id TEXT PRIMARY KEY NOT NULL REFERENCES cms_grant(id) ON DELETE CASCADE,translate_enabled INTEGER NOT NULL DEFAULT 0,narration_enabled INTEGER NOT NULL DEFAULT 0,images_enabled INTEGER NOT NULL DEFAULT 0,updated_by TEXT REFERENCES auth_user(id),updated_at INTEGER NOT NULL);
-- No API keys, prompts, scripts, generated content or upstream error bodies here.
CREATE TABLE cms_ai_activity(id TEXT PRIMARY KEY NOT NULL,provider_id TEXT NOT NULL,credential_id TEXT NOT NULL,project_id TEXT NOT NULL,actor_id TEXT REFERENCES auth_user(id) ON DELETE SET NULL,actor_name TEXT NOT NULL,course_id TEXT NOT NULL,module_id TEXT NOT NULL,page_id TEXT,block_id TEXT,locale TEXT NOT NULL,feature TEXT NOT NULL CHECK(feature IN ('translate','narration','images')),endpoint TEXT NOT NULL,requested_model TEXT NOT NULL,model TEXT,voice TEXT,quality TEXT,image_size TEXT,input_characters INTEGER NOT NULL,requested_images INTEGER,output_images INTEGER,output_bytes INTEGER,started_at INTEGER NOT NULL,finished_at INTEGER,http_status INTEGER,request_id TEXT,response_id TEXT,organization_id TEXT,usage_json TEXT,outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN ('pending','succeeded','rejected','unknown')),application_status TEXT NOT NULL DEFAULT 'not_applied' CHECK(application_status IN ('not_applied','generated','saved')),error_code TEXT,reconciled_at INTEGER,reconciled_by TEXT REFERENCES auth_user(id),reconciliation_note TEXT NOT NULL DEFAULT '',reconciliation_version INTEGER NOT NULL DEFAULT 0);
CREATE INDEX cms_ai_activity_provider_time ON cms_ai_activity(provider_id,started_at,id);
CREATE TABLE cms_ai_artifact(id TEXT PRIMARY KEY NOT NULL,activity_id TEXT NOT NULL REFERENCES cms_ai_activity(id),actor_id TEXT NOT NULL REFERENCES auth_user(id),module_id TEXT NOT NULL,page_id TEXT NOT NULL,block_id TEXT NOT NULL,metadata_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX cms_ai_artifact_page ON cms_ai_artifact(actor_id,page_id);
CREATE TABLE cms_ai_reconciliation_event(id TEXT PRIMARY KEY NOT NULL,activity_id TEXT NOT NULL REFERENCES cms_ai_activity(id),actor_id TEXT NOT NULL REFERENCES auth_user(id),reconciled INTEGER NOT NULL,note TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE UNIQUE INDEX cms_ai_artifact_activity ON cms_ai_artifact(activity_id);
